SELECT c.is_active, CASE WHEN c.age >= 56 THEN 'high' WHEN c.age >= 34 THEN 'mid' ELSE 'low' END AS age_bucket, SUM(CASE WHEN o.status = 'RETURNED' THEN o.shipping_fee ELSE 0 END) AS returned_shipping_fee, SUM(CASE WHEN o.status = 'CANCELLED' THEN o.shipping_fee ELSE 0 END) AS cancelled_shipping_fee FROM orders o INNER JOIN stores s ON o.store_id = s.id LEFT JOIN customers c ON o.customer_id = c.id WHERE s.city IN ('Berlin', 'London') GROUP BY c.is_active, CASE WHEN c.age >= 56 THEN 'high' WHEN c.age >= 34 THEN 'mid' ELSE 'low' END;
